import { get, handleApiError, post } from '@helpers/httpClient';

import { mapHikingRepairKit, mapHikingRepairKitUsage } from '../@mappers/hikingRepairKit.mapper';
import {
  IHikingRepairKitCreateDTO,
  IHikingRepairKitCreateResultDTO,
  IHikingRepairKitDeleteDTO,
  IHikingRepairKitDTO,
  IHikingRepairKitUpdateDTO,
  IHikingRepairKitUsageCreateDTO,
  IHikingRepairKitUsageCreateResultDTO,
  IHikingRepairKitUsageDeleteDTO,
  IHikingRepairKitUsageDTO,
} from '../@types/DTO/hikingRepairKit.dto.types';

export const getHikingRepairKitItems = async (id_hiking: number) => {
  const res = await get<IHikingRepairKitDTO[]>('/ajax/hiking/repair_kit/repair_kit_list.php', {
    id_hiking,
  });
  return res.map(mapHikingRepairKit);
};

export const addHikingRepairKitItem = async (data: IHikingRepairKitCreateDTO) => {
  const res = await post(
    '/ajax/hiking/repair_kit/repair_kit_add.php',
    data,
  ).then<IHikingRepairKitCreateResultDTO>(handleApiError);
  return +res.id;
};

export const updateHikingRepairKitItem = async (data: IHikingRepairKitUpdateDTO) => {
  const res = await post('/ajax/hiking/repair_kit/repair_kit_edit.php', data).then(handleApiError);
  return !!res;
};

export const deleteHikingRepairKitItem = async (data: IHikingRepairKitDeleteDTO) => {
  const res = await post('/ajax/hiking/repair_kit/repair_kit_del.php', data).then(handleApiError);
  return !!res;
};

// -------

export const getHikingRepairKitUsages = async (id_hiking: number) => {
  const res = await get<IHikingRepairKitUsageDTO[]>(
    '/ajax/hiking/repair_kit/repair_kit_usages_list.php',
    { id_hiking },
  );
  return res.map(mapHikingRepairKitUsage);
};

export const addHikingRepairKitUsages = async (data: IHikingRepairKitUsageCreateDTO) => {
  const res = await post(
    '/ajax/hiking/repair_kit/repair_kit_usages_add.php',
    data,
  ).then<IHikingRepairKitUsageCreateResultDTO>(handleApiError);
  return +res.id;
};

export const deleteHikingRepairKitUsages = async (data: IHikingRepairKitUsageDeleteDTO) => {
  const res = await post('/ajax/hiking/repair_kit/repair_kit_usages_del.php', data).then(
    handleApiError,
  );
  return !!res;
};
